input.old_string:
/* Student name cell with avatar */
.student-name-cell {
  display: flex;
  align-items: center;
  gap: 8px;
}
.student-name-cell strong {
  font-size: 15px;
}

input.new_string:
/* Student name cell with avatar */
.student-name-cell {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}
.student-name-cell strong {
  font-size: 15px;
  white-space: nowrap;
}

.table-scroll-wrap > table {
  min-width: 820px;
}

/* Prevent wrapping in key columns */
.student-row td:nth-child(4),
.student-row td:nth-child(5),
.student-row td:nth-child(6) {
  white-space: nowrap;
}
